import random
import string

def generate_test_case():
    length = random.randint(1, 10**3)
    s = ''.join(random.choices(string.ascii_letters + string.digits + ' '*10, k=length))
    while '  ' in s:
        s = s.replace('  ', ' ')
    if s[0] == ' ':
        s = s[1:]
    if s[-1] == ' ':
        s = s[:-1]
    return s
